#include <iostream>
#include <vector>
#include <string>
#include <unordered_map>
#include <list>
#include <algorithm>
using namespace std;

// Two Sum với unordered_map - O(n)
pair<int, int> twoSum(const vector<int>& a, int target) {
    unordered_map<int, int> viTri; // giá trị -> chỉ số
    for (int i = 0; i < (int)a.size(); i++) {
        auto it = viTri.find(target - a[i]);
        if (it != viTri.end()) return {it->second, i};
        viTri[a[i]] = i;
    }
    return {-1, -1};
}

// Nhóm các từ đảo chữ (Group Anagrams): chuỗi đã sắp xếp ký tự làm khóa
vector<vector<string>> groupAnagrams(const vector<string>& tu) {
    unordered_map<string, vector<string>> nhom;
    for (const string& s : tu) {
        string khoa = s;
        sort(khoa.begin(), khoa.end());
        nhom[khoa].push_back(s);
    }
    vector<vector<string>> kq;
    for (auto& [khoa, ds] : nhom) kq.push_back(ds);
    return kq;
}

// LRU Cache - get/put O(1): std::list giữ thứ tự dùng + unordered_map trỏ thẳng vào nút
class LRUCache {
    int sucChua;
    list<pair<int, int>> dsDung; // đầu danh sách = vừa dùng gần nhất
    unordered_map<int, list<pair<int, int>>::iterator> viTri;
public:
    explicit LRUCache(int c) : sucChua(c) {}
    int get(int key) {
        auto it = viTri.find(key);
        if (it == viTri.end()) return -1;
        dsDung.splice(dsDung.begin(), dsDung, it->second); // đưa lên đầu, O(1)
        return it->second->second;
    }
    void put(int key, int value) {
        auto it = viTri.find(key);
        if (it != viTri.end()) {
            it->second->second = value;
            dsDung.splice(dsDung.begin(), dsDung, it->second);
            return;
        }
        if ((int)dsDung.size() == sucChua) { // đầy: bỏ phần tử lâu nhất chưa dùng
            viTri.erase(dsDung.back().first);
            dsDung.pop_back();
        }
        dsDung.emplace_front(key, value);
        viTri[key] = dsDung.begin();
    }
};


