// Two Sum với unordered_map - O(n)
pair<int, int> twoSum(const vector<int>& a, int target) {
    unordered_map<int, int> viTri; // giá trị -> chỉ số
    for (int i = 0; i < (int)a.size(); i++) {
        auto it = viTri.find(target - a[i]);
        if (it != viTri.end()) return {it->second, i};
        viTri[a[i]] = i;
    }
    return {-1, -1};
}

// Nhóm các từ đảo chữ (Group Anagrams): chuỗi đã sắp xếp ký tự làm khóa
vector<vector<string>> groupAnagrams(const vector<string>& tu) {
    unordered_map<string, vector<string>> nhom;
    for (const string& s : tu) {
        string khoa = s;
        sort(khoa.begin(), khoa.end());
        nhom[khoa].push_back(s);
    }
    vector<vector<string>> kq;
    for (auto& [khoa, ds] : nhom) kq.push_back(ds);
    return kq;
}

